def wcorr(x,y,w):
    W=sum(w);mx=sum(a*b for a,b in zip(x,w))/W;my=sum(a*b for a,b in zip(y,w))/W
    cov=sum(wi*(a-mx)*(b-my) for a,b,wi in zip(x,y,w));vx=sum(wi*(a-mx)**2 for a,wi in zip(x,w));vy=sum(wi*(b-my)**2 for b,wi in zip(y,w))
    return cov/math.sqrt(vx*vy)
def rank(v): s=sorted(range(len(v)),key=lambda k:v[k]); r=[0]*len(v)
def spear(x,y):
    rx=[sorted(x).index(v) for v in x]; ry=[sorted(y).index(v) for v in y]; return wcorr(rx,ry,[1]*len(x))
def wslope(x,y,w):
    W=sum(w);mx=sum(a*b for a,b in zip(x,w))/W;my=sum(a*b for a,b in zip(y,w))/W
    return sum(wi*(a-mx)*(b-my) for a,b,wi in zip(x,y,w))/sum(wi*(a-mx)**2 for a,wi in zip(x,w))
